def minutes(label):
    m = re.search(r'\((\d+)', label)
    return int(m.group(1)) if m else 0


def act(id, title, lo, hi, group, equipment, shabbat, place, energy, depth, values, tags, character, rating, desc, goals, steps, notes, tip, shabbat_note, subtopics):
    """steps: שבעה שלבים לפי התבנית: פתיחה, משחק, מתודה, קטע קריאה, דיון (רשימה), הסבר, סיכום"""
    flow = []
    for label, body in steps:
        flow.append({'label': label, 'items': body} if isinstance(body, list) else {'label': label, 'body': body})
    bodies = [s[1] for s in steps]
    return dict(
        id=id, title=title, categorySlug='activities', subtopics=subtopics, ageMin=lo, ageMax=hi, duration=sum(minutes(s[0]) for s in steps),
        groupSize=group, equipment=equipment, shabbat=shabbat, place=place, energy=energy, depth=depth, values=values, tags=tags,
        rating=rating, character=character, description=desc, goals=goals,
        opening=bodies[0], game=bodies[1], method=bodies[2], discussion=bodies[4], guideNotes=notes, summary=bodies[6], tip=tip,
        shabbatNote=shabbat_note, flow=flow,
    )


